// ResourceServiceHandler is an implementation of the meurpg.play.v1.ResourceService service.
type ResourceServiceHandler interface {
	// GetRestPreview says, for each living, active player character, what a rest
	// would give back: nothing is written. Master only.
	//
	// Errors: `permission_denied` for a player; `failed_precondition` with no open
	// session.
	GetRestPreview(context.Context, *connect.Request[v1.GetRestPreviewRequest]) (*connect.Response[v1.GetRestPreviewResponse], error)
	// TakeRest records a short or a long rest for the whole party and gives back
	// what the SRD says each kind restores (see RestPreview): the resources by
	// their recharge, the spell slots (pact slots on a short rest too), and, on a
	// long rest, the hit points, half of the hit dice and the end of the temporary
	// hit points (and with them Aid) and of the slots Flexible Casting created.
	// The new vitals go out on the session's stream, and the rest is written to
	// the session's history. Master only.
	//
	// Errors: `permission_denied` for a player; `failed_precondition` with no open
	// session, or with ResourceBlocked COMBAT_OPEN while a combat is not ended;
	// `invalid_argument` for a hit dice choice that is not the character's.
	TakeRest(context.Context, *connect.Request[v1.TakeRestRequest]) (*connect.Response[v1.TakeRestResponse], error)
	// SpendHitDice spends one hit die of the character on a short rest: the die
	// is rolled and the Constitution modifier added, and the character regains
	// that many hit points (SRD 5.1, "Short Rest"). The player decides whether to
	// spend another one after each roll, so one call spends one die. The
	// character's player or the master.
	//
	// Song of Rest (SRD 5.1, Bard 2): when the latest rest of the open session is a
	// short rest, a bard of the party with at least 1 hit point has the feature, and
	// this is the first die the character spends since that rest, the character
	// regains an extra die of the song (d6, d8 from bard level 9, d10 from 13, d12
	// from 17, the largest among the bards) once for the rest. The party hears the
	// song: anyone who rests with a bard does, the bard included. An app roll rolls
	// the extra die too; a typed roll sends its face in `typed_song_face`.
	//
	// Errors: `permission_denied` for another player's character;
	// `failed_precondition` with ResourceBlocked NO_HIT_DICE_LEFT, or
	// SONG_OF_REST_FACE_NEEDED for a typed roll that lacks the song's face;
	// `invalid_argument` for a die size the character does not have, or a typed face
	// outside its die.
	SpendHitDice(context.Context, *connect.Request[v1.SpendHitDiceRequest]) (*connect.Response[v1.SpendHitDiceResponse], error)
	// UseArcaneRecovery spends the wizard's once-a-day use and recovers the chosen
	// expended spell slots, after a short rest (SRD 5.1, Wizard, Arcane Recovery):
	// the slots may have a combined level of half the WIZARD level (rounded up) at
	// most, and none of them can be of the 6th level or higher. Only the character's
	// spellcasting slots count, never the pact slots. "Once per day" is once per
	// long rest: the use is the `arcane_recovery` resource, which a long rest gives
	// back. It is allowed only while the latest rest of the open session is a short
	// rest. The character's player or the master.
	//
	// With `feature_key` the call is the table feature's slot_recovery effect instead:
	// it spends a use of the effect's resource and keeps to the effect's highest slot level
	// and combined level, with the same short rest and the same refusals (NOT_AVAILABLE is
	// the character not having the feature).
	//
	// Errors: `permission_denied` for another player's character;
	// `invalid_argument` for no slots, a repeated level or a count below 1;
	// `failed_precondition` with ResourceBlocked NOT_AVAILABLE (not a wizard),
	// NO_USES_LEFT (used since the last long rest), NO_SHORT_REST (the latest rest is
	// not a short rest), SLOT_LEVEL_TOO_HIGH (a slot of the 6th level or higher),
	// SLOT_NOT_EXPENDED (fewer expended slots of that level than asked) and
	// OVER_ALLOWANCE (the combined level is above the allowance; needed is the
	// combined level asked and available the allowance).
	UseArcaneRecovery(context.Context, *connect.Request[v1.UseArcaneRecoveryRequest]) (*connect.Response[v1.UseArcaneRecoveryResponse], error)
	// UseNaturalRecovery is the Circle of the Land druid's Natural Recovery (SRD 5.1,
	// Druid 2), the same recovery as UseArcaneRecovery with the DRUID level: expended
	// spell slots of a combined level up to half the druid level (rounded up) come back
	// after a short rest, none of the 6th level or higher, once per long rest (the
	// `natural_recovery` resource). The pact slots never count. The character's player
	// or the master.
	//
	// Errors: as UseArcaneRecovery, with NOT_AVAILABLE for a character that has no
	// Natural Recovery (not a druid of the Circle of the Land).
	UseNaturalRecovery(context.Context, *connect.Request[v1.UseNaturalRecoveryRequest]) (*connect.Response[v1.UseNaturalRecoveryResponse], error)
	// UseLayOnHands touches a creature and draws from the pool: heals up to the
	// amount, or spends 5 points to cure a disease or neutralize a poison (SRD
	// 5.1, Paladin). The touch is an action of the paladin's turn. Whatever the
	// creature is, the action and the points are spent; on an undead or a
	// construct the touch has no effect, and the answer does not say why.
	//
	// Errors: the combat's (EncounterBlocked: not the combatant's turn, ACTION_USED);
	// `failed_precondition` with ResourceBlocked NOT_ENOUGH_POINTS;
	// `invalid_argument` for an amount outside 1 to what the pool has left.
	UseLayOnHands(context.Context, *connect.Request[v1.UseLayOnHandsRequest]) (*connect.Response[v1.UseLayOnHandsResponse], error)
	// CreateSpellSlot turns sorcery points into a spell slot of level 1 to 5 as a
	// bonus action (SRD 5.1, Sorcerer, Flexible Casting). The slot vanishes on a
	// long rest.
	//
	// Errors: the combat's (BONUS_ACTION_USED); ResourceBlocked NOT_ENOUGH_POINTS
	// and SLOT_LEVEL_TOO_HIGH.
	CreateSpellSlot(context.Context, *connect.Request[v1.CreateSpellSlotRequest]) (*connect.Response[v1.CreateSpellSlotResponse], error)
	// ConvertSpellSlot expends a free spell slot for as many sorcery points as its
	// level, as a bonus action. Refused when the points would pass the maximum
	// (the sorcerer's level).
	//
	// Errors: the combat's; ResourceBlocked NO_FREE_SLOT, SORCERY_POINTS_FULL and
	// SORCERY_POINTS_OVER.
	ConvertSpellSlot(context.Context, *connect.Request[v1.ConvertSpellSlotRequest]) (*connect.Response[v1.ConvertSpellSlotResponse], error)
	// GiveBardicInspiration gives a creature a die for 10 minutes (100 rounds) as
	// a bonus action, spending one use. The target is not the bard, is seen within
	// 60 feet, hears the bard and holds no die yet.
	//
	// Errors: the combat's; ResourceBlocked NO_USES_LEFT, TARGET_REFUSED.
	GiveBardicInspiration(context.Context, *connect.Request[v1.GiveBardicInspirationRequest]) (*connect.Response[v1.GiveBardicInspirationResponse], error)
	// AnswerBardicInspiration answers the question a held attack roll asks: use
	// the die on it, or keep it. RollAttack holds the result of a character that has
	// a die until this call (the roll is only resolved after the answer: SRD 5.1
	// lets the creature wait until after the d20 and decide before the GM says
	// whether the roll succeeds). The roll's owner or the master.
	//
	// Errors: `not_found` for a hold that is gone; `invalid_argument` for a typed
	// face outside the die.
	//
	// Deprecated (E4-9): AnswerHeldRoll answers every question of a held roll, whoever asks it. This RPC is still
	// served, as an adapter over the same answer, for a tab opened before AnswerHeldRoll existed.
	//
	// Deprecated: do not use.
	AnswerBardicInspiration(context.Context, *connect.Request[v1.AnswerBardicInspirationRequest]) (*connect.Response[v1.AnswerBardicInspirationResponse], error)
	// AnswerLucky answers the question a held attack roll asks when a halfling's d20 shows a 1
	// (SRD 5.1, Halfling, Lucky: the die may be rolled again, and the new roll stands): roll it
	// again, or keep the 1. RollAttack holds the result of a halfling's weapon attack or attack
	// cantrip whose d20 shows a 1 until this call (RollAttackResponse.lucky_offer); with advantage
	// or disadvantage the question comes when either die shows a 1, even the one that does not
	// count, and only that die is rolled again (one of them when both show a 1). The new die is
	// rolled in the app or typed from a real die (RN-18, as for the d20); the new roll is never
	// asked about again, even when it is a 1. When the attacker also holds a Bardic Inspiration
	// die the roll stays held after the answer and the response carries the die's question on the
	// new roll (RollAttackResponse.inspiration_offer, answered with AnswerBardicInspiration);
	// otherwise the attack is resolved, as RollAttack would have resolved it with the new d20. The
	// roll's owner or the master.
	//
	// Errors: `not_found` for a hold that is gone; `permission_denied` for another player's roll;
	// `invalid_argument` without roll_in_app or typed_face when reroll is set, or a typed face
	// outside 1 to 20; `failed_precondition` when the hold asks no Lucky question or it was
	// answered already (by another answer); EncounterBlocked WRONG_DICE_MODE for a player's way of
	// rolling the campaign does not allow.
	//
	// Deprecated (E4-9): AnswerHeldRoll answers every question of a held roll, whoever asks it. This RPC is still
	// served, as an adapter over the same answer, for a tab opened before AnswerHeldRoll existed.
	//
	// Deprecated: do not use.
	AnswerLucky(context.Context, *connect.Request[v1.AnswerLuckyRequest]) (*connect.Response[v1.AnswerLuckyResponse], error)
	// GetOutsideInspiration reads the Bardic Inspiration of the caller out of a combat: the
	// die their character holds and, for a bard, the uses left and the party to give it to;
	// and the caller's rolls that wait for an answer, about the die or the halfling's Lucky.
	// Only the caller's own character is described (the master gets every die held).
	GetOutsideInspiration(context.Context, *connect.Request[v1.GetOutsideInspirationRequest]) (*connect.Response[v1.GetOutsideInspirationResponse], error)
	// GiveBardicInspirationOutside gives a die to another character of the party outside
	// a combat, spending one use: the die lasts 10 minutes of game time. The target
	// is another character of the campaign who holds no die; the bard's player gives with
	// their own character. While a combat runs, GiveBardicInspiration is the call.
	//
	// Errors: ResourceBlocked NO_USES_LEFT, TARGET_REFUSED, NOT_AVAILABLE,
	// COMBAT_OPEN (a combat is open: give in it).
	GiveBardicInspirationOutside(context.Context, *connect.Request[v1.GiveBardicInspirationOutsideRequest]) (*connect.Response[v1.GiveBardicInspirationOutsideResponse], error)
	// AnswerOutsideInspiration answers the question a d20 roll asks when its character holds a
	// die and the roll is not a weapon attack (RollAttack has AnswerBardicInspiration): use the
	// die on it or keep it. The rolls that ask are RollSceneCheck, RollGroupCheck,
	// SearchForTraps (out of a combat) and TryPuzzleHint, and, for a player's character in a
	// combat, CastSpell (a spell attack against one target), RollEffectSave and
	// ResolveConcentrationSave; the die is the character's out of a combat and its combatant's
	// in one. The roll is then written as if it had been made now, with the d20 it rolled and
	// the die added when it was used, by the very path that held it (the held request is run
	// again with the d20 already rolled). The roll's owner only. A roll of the master, and the
	// saves the app rolls for a target (a spell's saving throw, a hit rider's), never ask.
	//
	// Errors: `not_found` for a hold that is gone; `invalid_argument` for a typed face outside
	// the die; `failed_precondition` when the die ran out meanwhile; ResourceBlocked
	// LUCKY_PENDING while the Lucky question of the same roll waits (AnswerOutsideLucky first).
	//
	// Deprecated (E4-9): AnswerHeldRoll answers every question of a held roll, whoever asks it. This RPC is still
	// served, as an adapter over the same answer, for a tab opened before AnswerHeldRoll existed.
	//
	// Deprecated: do not use.
	AnswerOutsideInspiration(context.Context, *connect.Request[v1.AnswerOutsideInspirationRequest]) (*connect.Response[v1.AnswerOutsideInspirationResponse], error)
	// AnswerOutsideLucky answers the Lucky question of a d20 roll that is not a weapon attack
	// (AnswerLucky has those): a halfling's d20 showed a 1 (SRD 5.1, Halfling, Lucky: the die may
	// be rolled again, and the new roll stands), so roll it again, or keep the 1. The rolls that
	// ask are the ones that wait for a Bardic Inspiration die (AnswerOutsideInspiration):
	// RollSceneCheck, RollGroupCheck, SearchForTraps (not the Search action of a combat) and
	// TryPuzzleHint, and, for a player's character in a combat, CastSpell (a spell attack against
	// one target), RollEffectSave and ResolveConcentrationSave. Each answers with `lucky_offer`
	// instead of its result when the roller's player rolls it for their own halfling and a d20
	// shows a 1; with advantage or disadvantage the question comes when either die shows a 1, even
	// the one that does not count, and only that die is rolled again (the first when both do). The
	// new die is rolled in the app or typed from a real die (RN-18, as for the d20); the new roll is
	// never asked about again, even when it is a 1, and Reliable Talent counts it as it counts any
	// d20 of the check. When the character also holds a Bardic Inspiration die the roll stays held
	// after the answer, and the result is the path's response with `inspiration_offer` on the new
	// roll (answered with AnswerOutsideInspiration); otherwise the roll is written as the path
	// writes it, with the d20 rolled again in its roll's `rerolled` ("trait:lucky"). The roll's
	// owner only: the master's rolls never ask (a roll the master makes for a halfling waits for a
	// decision, MR-014).
	//
	// Errors: `not_found` for a hold that is gone or another player's; `invalid_argument` without
	// roll_in_app or typed_face when reroll is set, or a typed face outside 1 to 20;
	// `failed_precondition` when the hold asks no Lucky question, it was answered already (by
	// another answer) or its combat round is over; the path's WRONG_DICE_MODE for a way of rolling
	// the campaign does not allow.
	//
	// Deprecated (E4-9): AnswerHeldRoll answers every question of a held roll, whoever asks it. This RPC is still
	// served, as an adapter over the same answer, for a tab opened before AnswerHeldRoll existed.
	//
	// Deprecated: do not use.
	AnswerOutsideLucky(context.Context, *connect.Request[v1.AnswerOutsideLuckyRequest]) (*connect.Response[v1.AnswerOutsideLuckyResponse], error)
	// AnswerHeldRoll answers the question of any roll that waits, whichever roll it is (a weapon attack,
	// a spell attack, a save, a check, a search, a hint try) and whichever question it asks (the
	// halfling's Lucky, or the Bardic Inspiration die): the one RPC AnswerLucky, AnswerBardicInspiration,
	// AnswerOutsideLucky and AnswerOutsideInspiration are the older forms of. The roll is run again by the
	// path that held it, with the d20 already rolled and the answer applied, and the response is that path's
	// own (`result`), still held with the roll's next question (`next`, copied out of the result so the app
	// needs no code for each kind), or resolved and written.
	//
	// Who may answer: the roller's player, and the master, for every roll that waits, in a combat or out
	// of it (it unblocks a player who left). Both may try at once; the first answer wins and the other gets
	// `failed_precondition` (the roll was answered already), the die spent once. Another player gets
	// `not_found`, never "permission denied", which would say the roll exists.
	//
	// The master waits for the player's first chance (E4-10): for 10 s after the question was asked
	// (`HeldRollOffer.created_at`), only the roller's player may answer it, and the master's answer is refused
	// with `failed_precondition` and ResourceBlocked PLAYER_FIRST (`RESOURCE_BLOCKED_REASON_PLAYER_FIRST`), whose
	// `wait_seconds` says how long is left. It does not apply when no player plays the roll (an NPC's, or a
	// player who left). This holds for the master's own rolls for a player's character (a save, a spell attack,
	// a group check) too: the master is asked in his own sheet, the player reads the same question, and the first
	// answer after the 10 s wins.
	//
	// The response is rendered for the member who answers, whoever rolled.
	// The same answer given again is rendered the same way.
	//
	// Errors: `not_found` for a hold that is gone or one the caller may not answer; `invalid_argument`
	// for an answer of the wrong question, for a missing roll_in_app or typed_face, or a typed face outside
	// the die; ResourceBlocked LUCKY_PENDING for the die's answer while the Lucky question of the same
	// roll waits; `failed_precondition` when the die ran out or the roll was answered already; the path's
	// WRONG_DICE_MODE for a way of rolling the campaign does not allow (the master rolls either way).
	AnswerHeldRoll(context.Context, *connect.Request[v1.AnswerHeldRollRequest]) (*connect.Response[v1.AnswerHeldRollResponse], error)
	// ListHeldRolls lists the questions of the rolls that wait and the caller may answer, oldest first: a
	// player's own rolls, in a combat and out of one; the master's, every roll of the campaign. A question
	// whose combat round is over, or whose die ran out, is not listed. Read it again when the stream says
	// HeldRollsChanged.
	ListHeldRolls(context.Context, *connect.Request[v1.ListHeldRollsRequest]) (*connect.Response[v1.ListHeldRollsResponse], error)
}

